 mutating func release()->Int? {held=false;return unmutedCall}
 mutating func unmuteFinished(_ call:Int, succeeded:Bool)->Int? {guard pendingCall==call else{return nil};pendingCall=nil;guard succeeded else{return nil};unmutedCall=call;return held ? nil:call}
 mutating func beginRestore(_ call:Int)->Bool {guard unmutedCall==call else{return false};unmutedCall=nil;return true}
 mutating func interrupt()->Int? {let call=unmutedCall ?? pendingCall;held=false;pendingCall=nil;unmutedCall=nil;return call}
 static func tests()->Bool {var p=PTTCoordinator();guard p.press(1,muted:true)==1,p.release()==nil,p.unmuteFinished(1,succeeded:true)==1,p.beginRestore(1) else{return false};var initiallyUnmuted=PTTCoordinator();guard initiallyUnmuted.press(1,muted:false)==nil else{return false};var repeated=PTTCoordinator();guard repeated.press(1,muted:true) != nil,repeated.press(1,muted:true)==nil else{return false};var changed=PTTCoordinator();guard changed.press(1,muted:true) != nil,changed.unmuteFinished(1,succeeded:true)==nil,changed.release()==1,!changed.beginRestore(2),changed.beginRestore(1) else{return false};return true}
}
