 static func post(_ pid:pid_t,_ key:Int)->Bool{guard let s=CGEventSource(stateID:.combinedSessionState) else{return false};for(k,d,f) in [(CGKeyCode(kVK_Shift),true,CGEventFlags.maskShift),(CGKeyCode(kVK_Command),true,[.maskCommand,.maskShift]),(CGKeyCode(key),true,[.maskCommand,.maskShift]),(CGKeyCode(key),false,[.maskCommand,.maskShift]),(CGKeyCode(kVK_Command),false,.maskShift),(CGKeyCode(kVK_Shift),false,[])]{guard let e=CGEvent(keyboardEventSource:s,virtualKey:k,keyDown:d)else{return false};e.flags=f;e.postToPid(pid);usleep(20000)};return true}
